\label{defn: alpha}
    Let ${\mathfrak{A}}=(X,\mathcal{F},B,{\bf{M}},t)$ be a projective adjoint foliated structure and let $L$ be an $\mathbb R$-divisor on $X$. We define \emph{Tian's $\alpha$-invariant}
    $\alpha({\mathfrak{A}};L)$ of $L$ with respect to ${\mathfrak{A}}$ as
    \[\alpha({\mathfrak{A}};L):=\sup\{s\geq 0\mid ({\mathfrak{A}},sD)\text{ is lc for any }0\leq D\sim_{\mathbb R}L\}.\]

If $|-K_{{\mathfrak{A}}}|_{\mathbb R}\neq\emptyset$, then we define 
\emph{Tian's $\alpha$-invariant} 
$\alpha({\mathfrak{A}})$ of ${\mathfrak{A}}$ as $\alpha({\mathfrak{A}}):=\alpha({\mathfrak{A}};-K_{{\mathfrak{A}}})$. For any pair $(X,\Delta)$ and any point $x \in X$, we also define the \emph{local Tian's $\alpha$-invariant} 
  $\alpha(X\ni x,\Delta;L)$ of $L$ at $x \in X$
  as
    \[\alpha(X\ni x,\Delta;L):=\sup\{s\geq 0\mid (X,\Delta+sD)\text{ is lc near }x\text{ for any }0\leq D\sim_{\mathbb R}L\}.\]

\label{defn: sing of nfs}
Let ${\mathfrak{B}}/U=(X,\mathcal{F},B,{\bf{M}})(t)$ be a sub-normalized foliated structure. 

For any prime divisor $E$ over $X$, we define 
\begin{align*}
a(E,{\mathfrak{B}}):=a(E,\log{\mathfrak{B}})
\quad \text{and} \quad
{\operatorname{tmld}}({\mathfrak{B}}):={\operatorname{tmld}}(\log{\mathfrak{B}}).
\end{align*}
We say that ${\mathfrak{B}}$ is $\epsilon$-lc (resp. $\epsilon$-klt, lc, klt, plt) if $\log{\mathfrak{B}}$ is $\epsilon$-lc (resp. $\epsilon$-klt, lc, klt, plt). An lc place (resp. lc center) of ${\mathfrak{B}}$ is an lc place (resp. lc center) of $\log{\mathfrak{B}}$. We say that ${\mathfrak{B}}$ is \emph{qdlt} if ${\mathfrak{B}}$ is lc, $(X,B,{\bf{M}})$ is qdlt (cf.~\cite[Definition~7.1.1]{CHLX23}), and any lc center of ${\mathfrak{B}}$ is an lc center of $(X,B,{\bf{M}})$.

We may assume that $s<1$, otherwise ${\mathfrak{B}}={\mathfrak{B}}'$ and we may take ${\mathfrak{B}}_r={\mathfrak{B}}$ for any $r\in [0,1)$. Write ${\mathfrak{B}}=(X,\mathcal{F},B,{\bf{M}})(t)/U$ and ${\mathfrak{B}}'=(X,\mathcal{F},B',{\bf{M}}')(t')/U$. We take $a_r:=\frac{s-r}{1-r}$. 
If $t=t'$, then it suffices to define
    \begin{align*}
        {\mathfrak{B}}_r:=\left(X,\mathcal{F},\frac{1-r}{1-s}B'-\frac{s-r}{1-s}B,\frac{1-r}{1-s}{\bf{M}}'-\frac{s-r}{1-s}{\bf{M}}\right)(t).
    \end{align*}
If $t>t'$, then it suffices to define
    \begin{align*}
    {\mathfrak{B}}_r:=\left(X,\mathcal{F},B_r,\frac{1-r}{1-s}{\bf{M}}'-\frac{s-r}{1-s}{\bf{M}}\right)\left(\frac{(1-r)t'-(s-r)t}{1-s}\right),
    \end{align*}
where
    \begin{align*}
    B_r:=\left(\frac{1-r}{1-s}B'-\frac{s-r}{1-s}B\right)^{\operatorname{ninv}}+\frac{1}{(1-t')-a_r(1-t)}((1-t')B'^{\operatorname{inv}}-a_r(1-t)B^{\operatorname{inv}}).
    \end{align*}

\label{defn: bounded nfs}
Let $\mathcal{P}$ be a set of projective quasi-normalized foliated structures. We say that $\mathcal{P}$ is \emph{bounded} if there exist a bounded set of projective foliated pairs $\mathcal{Q}$ and a positive integer $r$ satisfying the following. For any ${\mathfrak{B}}:=(X,\mathcal{F},B,{\bf{M}})(t)\in\mathcal{P}$, there exists a very ample divisor $H$ on $X$, such that:
\begin{enumerate}
    \item $(X,\mathcal{F})\in\mathcal{Q}$.
    \item $H^{\dim X}\leq r$.
    \item $-r\leq (K_X+\operatorname{Supp} B+{\bf{M}}_X)\cdot H^{\dim X-1}\leq r$.
\end{enumerate}
Note that this aligns with Definition~\ref{defn: bounded pairs} (cf.~\cite[Lemma~2.20]{Bir19}) and the definition of bounded generalized pairs in the literature (cf.~\cite[Definition~1.1(5)]{Bir21b}).

\label{lem: CS25 3.13(4) general case}
Let $(X,S)$ be a plt pair where $S$ is a prime divisor, $\mathcal{F}$ a foliation on $X$, and $D$ a prime divisor on $S$ with generic point $\eta_D$. Let $r$ be the Cartier index of $K_X+S$ near $\eta_D$ and let $\mathcal{F}_S:=\mathcal{F}|_S$. Then there exists a non-negative integer $a$ such that, after possibly shrinking $X$ to a neighborhood of $\eta_D$, the following hold.
\begin{enumerate}
    \item For any prime divisor $P$ on $X$, $rD$ is Cartier, and we have
    $$(K_X+S)|_S=K_S+\frac{r-1}{r}D.$$
    \item We may write
    $$(K_{\mathcal{F}}+\epsilon_{\mathcal{F}}(S)S)|_S=K_{\mathcal{F}_S}+\frac{a+(r-1)\epsilon_{\mathcal{F}_S}(D)}{r}D.$$
    \item If $\epsilon_{\mathcal{F}}(S)=0$, then $a=0$ if and only if $\eta_D\not\in\mathrm{Sing}(\mathcal{F})$.
    \item Let $V\neq S$ be an $\mathcal F$-invariant prime divisor such that $D \subset V\cap S$. If $\epsilon_{\mathcal F}(S) = 0$ and $\epsilon_{\mathcal F_S}(D) = 1$, then $\eta_D \in \mathrm{Sing} ~ \mathcal F$.
\end{enumerate}

\label{prop: explicit formula}
   Notation and conditions as in Set-up~\ref{setup: pa no m}. Let $D$ be a prime divisor on $S$. Let $r:=r_D$, $\epsilon:=\epsilon_{\mathcal{F}_S}(D)$, $p_i:=p_{i,D},q_k:=q_{k,D},\lambda_j:=\lambda_{j,D}$, and $a:=a_D$. Then for any $\bm{v}=(b_1,\dots,b_l,c_1,\dots,c_m,\mu_1,\dots,\mu_n)\in\mathbb R^{l+m+n}$ and $t\in [0,1]$, we have
   $$\operatorname{mult}_DB_S(\bm{v},t)=\frac{1}{r}\left(t(a+\epsilon(r-1))+\sum_{i=1}^lp_ib_i+(1-t)\left(r-1+\sum_{k=1}^mq_kc_k\right)+\sum_{j=1}^n\lambda_j\mu_j\right).$$

\label{thm: dcc precise adjunction}
Let $\Gamma\subset [0,+\infty)$ be a DCC set and $\Gamma_0\subset [0,+\infty)$ a finite set. Then there exist a DCC set $\Gamma'\subset [0,1]$ and a finite set $\Gamma_0'$ depending only on $\Gamma$ and $\Gamma_0$ satisfying the following.

Notation and conditions as in Set-up~\ref{setup: pa no m}. Assume that $\bm{v},t\in\Gamma$. Let $D$ be a prime divisor on $S$. Let $r:=r_D$, $\epsilon:=\epsilon_{\mathcal{F}_S}(D)$, $p_i:=p_{i,D},q_k:=q_{k,D},\lambda_j:=\lambda_{j,D}$, and $a:=a_D$. Assume that $\operatorname{mult}_DB_S(\bm{v},t)\leq t\epsilon+(1-t)$.
\begin{enumerate}
    \item Assume that $\epsilon=0$ and $t<1$. Then:
    \begin{enumerate}
        \item We have
            $\frac{1}{1-t}\operatorname{mult}_DB_S(\bm{v},t)\in\Gamma'.$
        \item Assume that $\frac{1}{1-t}\operatorname{mult}_DB_S(\bm{v},t)\in\Gamma_0$. Then for any $i,k,j$,
        $$ta,tp_ib_i,q_kc_k,t\lambda_j\mu_j\in\Gamma_0'.$$
      In particular, either $t\in\Gamma_0'$, or $s\mapsto\frac{1}{1-s}\operatorname{mult}_DB_S(\bm{v},s)$ is a constant function.
    \end{enumerate}
\item Assume that $\mathcal{F}$ is algebraically integrable, ${\mathfrak{A}}(\bm{v},t)$ is lc, and $\epsilon=1$. Then:
  \begin{enumerate}
        \item We have
            $\operatorname{mult}_DB_S(\bm{v},t)\in\Gamma'.$
        \item Assume that $\operatorname{mult}_DB_S(\bm{v},t)\in\Gamma_0$.
        \begin{enumerate}
            \item If $a=0$, then $q_k=0$ and $p_ib_i,\lambda_j\mu_j\in\Gamma_0'$.
            \item If $a>0$, then for any $i,j$,
            $$t(a-1),p_ib_i,\lambda_j\mu_j\in\Gamma_0',$$
            and either $t=1$ or $q_kc_k\in\Gamma_0'$ for any $k$.
        \end{enumerate}
In particular, either $t\in\Gamma_0'$, or $s\mapsto\operatorname{mult}_DB_S(\bm{v},s)$ is a constant function.
    \end{enumerate}
\end{enumerate}

\label{thm: acc lct general version}
Let $d$ be a positive integer and $\Gamma\subset [0,+\infty)$ a DCC set. Then there exists a positive real number $\tau=\tau_{\operatorname{ilct}}(d,\Gamma)\in (0,1)$ depending only on $d$ and $\Gamma$ satisfying the following. 

Let ${\mathfrak{B}}=(X,\mathcal{F},B,{\bf{M}})(t)/U$ and ${\mathfrak{B}}'=(X,\mathcal{F},B',{\bf{M}}')(t')/U$ be two algebraically integrable normalized foliated structures of dimension $d$. Assume that
\begin{enumerate}
\item ${\mathfrak{B}}/U\in\Gamma$,
\item ${\mathfrak{B}}/U\geq{\mathfrak{B}}'/U\geq{\mathfrak{B}}^{1-\tau}/U$, and
\item ${\mathfrak{B}}'$ is lc.
\end{enumerate}
Then ${\mathfrak{B}}$ is lc.

\label{thm: global acc general}
Let $d$ be a positive integer and $\Gamma\subset [0,1]$ a DCC set. Then there exists a finite set $\Gamma_0=\Gamma_0(d,\Gamma)$ depending only on $d$ and $\Gamma$ satisfying the following. 

Assume that ${\mathfrak{B}}/U=(X,\mathcal{F},B,{\bf{M}})(t)/U$ is an lc algebraically integrable normalized foliated structure of dimension $d$ such that the associated morphism $\pi: X\rightarrow U$ is a contraction. Let $F$ be a general fiber of $\pi$. Assume that
\begin{itemize}
\item $K_{{\mathfrak{B}}}|_F\equiv0$, and
\item $B,t\in\Gamma$ and ${\bf{M}}=\sum\mu_j{\bf{M}}_j$, where each $\mu_j\in\Gamma$ and each ${\bf{M}}_j$ is nef$/U$ $\bm{b}$-Cartier.
\end{itemize}
Then:
\begin{enumerate}
    \item $B^{\operatorname{ninv}}|_F\in\Gamma_0$, and $B|_F\in\Gamma_0$ if $t<1$.
    \item $\{\mu_j\mid {\bf{M}}_j|_{F}\not\equiv\bm{0}\}\subset\Gamma_0$.
    \item Let ${\mathfrak{B}}(s):=(X,\mathcal{F},B,{\bf{M}})(s)$ for any $s\in [0,1]$. Assume that $K_{{\mathfrak{B}}(s)}$ is $\mathbb R$-Cartier for any $s\in [0,1]$. Then either $t\in\Gamma_0$, or $K_{{\mathfrak{B}}(s)}|_F\equiv 0$ for any $s\in [0,1]$.
\end{enumerate}

\label{lem: neg lem for generalized boundary}
    Let $X$ be a normal quasi-projective variety, $B\geq 0$ an $\mathbb R$-divisor on $X$, and ${\bf{M}}$ a nef$/X$ $\bm{b}$-divisor on $X$, such that $B+{\bf{M}}_X$ is $\mathbb R$-Cartier. Let $h\colon X'\rightarrow X$ be a projective birational morphism and $B':=h^{-1}_*B$. Then
    $$h^*(B+{\bf{M}}_X)\geq B'+{\bf{M}}_{X'}.$$

\label{lem: lc preserved under inequality}
Let ${\mathfrak{B}}/U$ be an algebraically integrable normalized foliated structure and ${\mathfrak{B}}'/U$ an algebraically integrable sub-normalized foliated structure, such that ${\mathfrak{B}}/U\geq{\mathfrak{B}}'/U$ and ${\mathfrak{B}}/U$ is lc. Let $t$ and $t'$ be the parameters of ${\mathfrak{B}}$ and ${\mathfrak{B}}'$, respectively. Assume that either $t<1$ or $t=t'=1$. Then:
\begin{enumerate}
    \item ${\mathfrak{B}}'$ is lc.
    \item Assume that $t'>0$ or $t=t'=0$. Then any lc place of ${\mathfrak{B}}'$ is an lc place of ${\mathfrak{B}}$.
\end{enumerate}

Since $X$ is klt and klt is an open condition, it follows that $\mu>0$. Since $\mu t<1$, by Lemma~\ref{lem: lc preserved under inequality}, ${\mathfrak{B}}^s$ is lc for any $s\in [0,\mu)$. If ${\mathfrak{B}}^s$ is not klt 
for some $s\in [0,\mu)$, then $s>0$ and there exists an lc place $E$ of ${\mathfrak{B}}^s$. By Lemma~\ref{lem: lc preserved under inequality}, $E$ is an lc place of ${\mathfrak{B}}^r$ for any $r\in [s,\mu]$. Since $r\mapsto a(E,{\mathfrak{B}}^r)$ is a quadratic function,
$E$ is an lc place of ${\mathfrak{B}}^r$ for any $r\in [0,\mu]$. In particular, $E$ is an lc place of ${\mathfrak{B}}^0$ and hence an lc place of $X$. This is not possible.

\label{lem: extract unique lc place}
Let ${\mathfrak{B}}/U:=(X,\mathcal{F},B,{\bf{M}})(t)/U$ be an algebraically integrable normalized foliated structure such that $X$ is $\mathbb Q$-factorial klt and let 
$$\mu:=\sup\{s\in [0,1]\mid {\mathfrak{B}}^s\text{ is lc}\}.$$
Assume that $\mu t<1$ and that any lc place of ${\mathfrak{B}}^{\mu}$ is not on $X$. Then there exists a projective birational morphism $g: Y\rightarrow X$ satisfying the following.
\begin{enumerate}
    \item $g$ is a divisorial contraction of a prime divisor $E$ and $Y$ is $\mathbb Q$-factorial. In particular, $\rho(Y/X)=1$.
    \item $E$ is an lc place of ${\mathfrak{B}}^{\mu}$.
    \item ${\mathfrak{B}}_Y(s):=(g^{-1}_*{\mathfrak{B}}^s,E)$ is plt for any $s\in [0,\mu)$. In particular, $E$ is normal.
\end{enumerate}

