        \item ${\mathfrak{B}}/U\geq{\mathfrak{B}}'/U\geq{\mathfrak{B}}^{1-\tau}/U$, and
        \item ${\mathfrak{B}}'$ is lc and $K_{{\mathfrak{B}}'}\sim_{\mathbb R,U}0$.
    \end{enumerate}
    Then $K_{{\mathfrak{B}}''}\sim_{\mathbb R,U}0$ for any ${\mathfrak{B}}/U\geq{\mathfrak{B}}''/U\geq{\mathfrak{B}}'/U$.

\label{thm: big gap general}
    Let $d$ be a positive integer and $\Gamma\subset [0,+\infty)$ a DCC set. Then there exists a positive real number $\tau=\tau_{\operatorname{big}}(d,\Gamma)$ depending only on $d$ and $\Gamma$ satisfying the following.

    Let ${\mathfrak{B}}/U$ and ${\mathfrak{B}}'/U$ be two algebraically integrable normalized foliated structures of dimension $d$. Assume that
    \begin{enumerate}
        \item ${\mathfrak{B}}/U\in\Gamma$ and $K_{{\mathfrak{B}}}$ is big$/U$,
        \item ${\mathfrak{B}}/U\geq{\mathfrak{B}}'/U\geq{\mathfrak{B}}^{1-\tau}/U$, and
        \item ${\mathfrak{B}}'$ is lc.
    \end{enumerate}
    Then $K_{{\mathfrak{B}}'}$ is big$/U$.

\label{lem: elementary perturbation eb}
Let $p,n$ be two positive integers and $\Gamma\subset [0,+\infty)$ a DCC set. Then there exists a positive integer $m_0:=m_0(p,n,\Gamma)\geq n+2$ depending only on $p$, $n$, and $\Gamma$ satisfying the following. Denote by $\gamma_p:=\frac{1}{p}\left\lfloor (p-1)\gamma\right\rfloor$ for any $\gamma\in\Gamma$. Then for any $\gamma\in\Gamma\backslash\{0\}$ and any real number $m\geq m_0$, we have the following.
    \begin{enumerate}
    \item $m(\gamma-\gamma_p)>1$ and $\lfloor m\gamma\rfloor>m\gamma_p$.
        \item Assume that $\gamma<1$. Then
        $$\frac{\left\lfloor\frac{m\gamma}{1-\gamma}\right\rfloor-\frac{n\gamma_p}{1-\gamma_p}}{m-n}>\frac{\gamma_p}{1-\gamma_p}.$$    \end{enumerate}

\label{thm: birational boundedness}
    Let $d$ be a positive integer, $\Gamma\subset [0,+\infty)$ a DCC set, and $C$ a positive real number. Assume that
    \begin{enumerate}
        \item ${\mathfrak{B}}=(X,\mathcal{F},B,{\bf{M}})(t)$ is a projective lc algebraically integrable normalized foliated structure,
        \item $\dim X=d$,
        \item ${\mathfrak{B}}\in\Gamma$ and $t\in (0,1)$, and
        \item $0<\operatorname{vol}(K_{{\mathfrak{B}}})\leq (1-t)^dC$.
    \end{enumerate}
   Then ${\mathfrak{B}}$ belongs to a log birationally bounded family.

\label{lem: volume monotonicity}
    Let ${\mathfrak{B}}\geq{\mathfrak{B}}'$ be two $\mathbb Q$-factorial lc algebraically integrable normalized foliated structures of dimension $d$. Let $t$ and $t'$ be the parameters of ${\mathfrak{B}}$ and ${\mathfrak{B}}'$, respectively. Assume that $t<1$. Then 
    $$\left(\frac{1}{1-t}\right)^d\operatorname{vol}(K_{{\mathfrak{B}}})\geq\left(\frac{1}{1-t'}\right)^d\operatorname{vol}(K_{{\mathfrak{B}}'}).$$

\label{lem: special model for eb}
Let $d$ and $p$ be positive integers. Then there exists a positive integer $q$ depending only on $d$ and $p$, and a projective birational morphism $f: W\rightarrow X$ satisfying the following. Assume that:
\begin{itemize}
    \item ${\mathfrak{B}}=(X,\mathcal{F},B,{\bf{M}})(t)$ is a projective klt algebraically integrable normalized foliated structure.
    \item $\dim X=d$, ${\mathfrak{B}}\in\frac{1}{p}\mathbb N$, and $t\in (0,1)$.
    \item $K_{{\mathfrak{B}}}$ is big.
\end{itemize}
Then:
\begin{enumerate}
\item $p\mid q$, $qK_{{\mathfrak{B}}}$ is integral, and $|qK_{{\mathfrak{B}}}|$ defines a birational map.
\item We have
        $$f^*(qK_{{\mathfrak{B}}})\sim A_W+R_W$$
    where $|A_W|$ is the movable part of $f^*|qK_{{\mathfrak{B}}}|$, $A_W$ is base-point-free and defines a birational morphism $g: W\rightarrow Y$.
\item ${\mathfrak{B}}_W:=\left(f^{-1}_*{\mathfrak{B}},\left(1-\frac{1}{q}\right)\operatorname{Exc}(f)\right)$ is $\frac{1}{pq}$-lc.
\end{enumerate}

\label{lem: gap exc threshold}
    Let $d$ be a positive integer and $\Gamma\subset [0,+\infty)$ a DCC set of real numbers. Then $\tau=\tau_{\operatorname{Rct}}(d,\Gamma\cup\{1\})$ as in Theorem~\ref{thm: rct general} satisfies the following. 

    Let ${\mathfrak{B}}(t)=(X,\mathcal{F},B,{\bf{M}})(t)$ be a projective normalized foliated structure of dimension $d$ such that $X$ is of Fano type, $B\in\Gamma,{\bf{M}}\in\mathrm{bNef}(X,\Gamma)$, $t\in [1-\tau,1)$, and ${\mathfrak{B}}(t)$ is $\mathbb R$-complementary but not exceptional. Then ${\mathfrak{B}}(s):=(X,\mathcal{F},B,{\bf{M}})(s)$ is $\mathbb R$-complementary but not exceptional for any $s\in [0,1)$.

\label{lem: alpha bound}
  Let $(X,B)$ be a projective klt pair of dimension $d$, $D$ a semi-ample $\mathbb R$-Cartier $\mathbb R$-divisor on $X$, and $L$ a big $\mathbb R$-divisor on $X$. Then for any $\epsilon>0$, we may pick $0\leq D'\sim_{\mathbb R}D$ such that
  $$\alpha(X,B+D';L)\geq \alpha(X,B;L)-\epsilon.$$

\label{thm: jiang principle general}
Let $d$ be a positive integer, $\Gamma\subset [0,+\infty)$ a DCC set, and $\epsilon$ a positive real number. Then the set of projective varieties $X$ such that
\begin{enumerate}
    \item ${\mathfrak{B}}:=(X,\mathcal{F},B)(t)$ is a projective algebraically integrable normalized foliated structure,
    \item $\dim X=d$,
    \item $-K_{{\mathfrak{B}}}$ is nef and $\alpha({\mathfrak{B}})^d\cdot\operatorname{vol}(-K_{{\mathfrak{B}}})\geq\epsilon$, and
    \item $t\leq 1-\epsilon$
\end{enumerate}
forms a bounded family. In addition, the set of $(X,\mathcal{F})$ such that (1-4) holds and 
\begin{enumerate}
    \item[(5)] $t\geq\epsilon$
\end{enumerate}
forms a bounded family.

Fix $n\in\{1,2,3,4\}$ and $d\in\{2,3\}$. 
\begin{enumerate}
    \item (Gap of lc threshold) Find the smallest positive real number $\tau=\tau_{\operatorname{ilct}}(n,d)$ such that for any $(X,\mathcal{F})\in\mathcal{P}_{n,d}$, if $\mathcal{F}$ is not lc, then $(X,\mathcal{F},t)$ is not lc for any $t>1-\tau$. Furthermore:
    \begin{enumerate}
        \item Classify all (singularities of) $(X,\mathcal{F})\in\mathcal{P}_{n,d}$ such that $(X,\mathcal{F},1-\tau)$ is lc but $\mathcal{F}$ is not lc.
    \end{enumerate}

    \item (Gap of global lc threshold) Find the smallest positive real number $\tau=\tau_{\operatorname{iglct}}(n,d)$ such that for any projective $(X,\mathcal{F})\in\mathcal{P}_{n,d}$, if $(X,\mathcal{F},t)$ is lc, $t>1-\tau$, and $K_{(X,\mathcal{F},t)}\equiv 0$, then $K_{\mathcal{F}}\equiv 0$. Furthermore:
    \begin{enumerate}
      \item Classify all projective $(X,\mathcal{F})\in\mathcal{P}_{n,d}$ such that $(X,\mathcal{F},1-\tau)$ is lc, $K_{(X,\mathcal{F},1-\tau)}\equiv 0$, but $K_{\mathcal{F}}\not\equiv 0$.  
    \end{enumerate}

    \item (Gap of pseudo-effective threshold) Find the smallest positive real number $\tau=\tau_{\operatorname{pet}}(n,d)$ such that for any projective $(X,\mathcal{F})\in\mathcal{P}_{n,d}$, if $K_{(X,\mathcal{F},1-\tau)}$ is not pseudo-effective, then $K_{(X,\mathcal{F},t)}$ is not pseudo-effective for any $t<1$. Furthermore:
    \begin{enumerate}
      \item Do we have $\tau_{\operatorname{pet}}(n,d)=\tau_{\operatorname{iglct}}(n,d)$?
      \item Classify all projective $(X,\mathcal{F})\in\mathcal{P}_{n,d}$ such that $(X,\mathcal{F},t)$ is lc, $K_{(X,\mathcal{F},1-\tau)}$ is pseudo-effective, but $K_{(X,\mathcal{F},t)}$ is not pseudo-effective for any $t<1-\tau$.
    \end{enumerate}

    \item (Gap of $\mathbb R$-complementary threshold) Find the smallest positive real number $\tau=\tau_{\operatorname{Rct}}(n,d)$ such that for any projective $(X,\mathcal{F})\in\mathcal{P}_{n,d}$, if $(X,\mathcal{F},t)$ is $\mathbb R$-complementary for some $t>1-\tau$, then $(X,\mathcal{F},t)$ is $\mathbb R$-complementary for any $t\in (1-\tau,1)$. Furthermore:
    \begin{enumerate}
        \item Classify all projective $(X,\mathcal{F})\in\mathcal{P}_{n,d}$ such that $(X,\mathcal{F},1-\tau)$ is $\mathbb R$-complementary but $(X,\mathcal{F},t)$ is not $\mathbb R$-complementary for any $t>1-\tau$. 
        \item Do we have $\tau_{\operatorname{iglct}}(n,d)=\tau_{\operatorname{Rct}}(n,d)$?
        \item Ask the same questions with the additional assumption that $X$ is of Fano type.
    \end{enumerate}

    \item (Explicit effective birationality) Find a set $\mathcal{S}_{\operatorname{eb}}\subset\mathbb N^+\times\mathbb N^+$ such that, for any projective $(X,\mathcal{F})\in\mathcal{P}_{n,d}$, the linear system
    $$|mK_X+nK_{\mathcal{F}}|$$
    defines a birational map for every $(m,n)\in\mathcal{S}_{\operatorname{eb}}$.

    \item (Exceptional Fanos) Find the smallest positive real number $\tau=\tau_{\mathrm{exc}}(n,d)$ such that for any $(X,\mathcal{F})\in\mathcal{P}_{n,d}$, if $X$ is of Fano type and $(X,\mathcal{F},t)$ is exceptional for some $t\in (1-\tau,1)$, then $(X,\mathcal{F},1-\tau)$ is exceptional. Furthermore:
    \begin{enumerate}
      \item Classify all exceptional $(X,\mathcal{F})\in\mathcal{P}_{n,d}$ such that $X$ is of Fano type, $(X,\mathcal{F},1-\tau)$ is exceptional, but $(X,\mathcal{F},t)$ is not exceptional for any $t\in (1-\tau,1)$.
      \item Construct the moduli for $(X,\mathcal{F})$ as in (a).
    \end{enumerate}
\end{enumerate}
One can also ask the same questions for structures with a polarization and with a boundary with standard coefficients.

\label{conj: boundedness of complements}
Let $d$ be a positive integer and $\Gamma\subset [0,1]$ a DCC set of rational numbers such that $\overline{\Gamma}\subset\mathbb Q$. Then there exists a positive integer $N$ depending only on $d$ and $\Gamma$ satisfying the following. 

Assume that ${\mathfrak{B}}:=(X,\mathcal{F},B)(t)$ is a projective $\mathbb R$-complementary normalized foliated structure such that $X$ is of Fano type and $t\in\Gamma$. Then there exists a monotonic $N$-complement ${\mathfrak{B}}^+$ of ${\mathfrak{B}}$ in the following sense.
\begin{enumerate}
    \item ${\mathfrak{B}}^+=(X,\mathcal{F},B^+)(t^+)\geq{\mathfrak{B}}$, i.e.\ $B^+\geq B$ and $t^+\geq t$.
    \item $Nt^+\in\mathbb N$, $NB^+$ is an integral divisor, and $NK_{{\mathfrak{B}}^+}\sim 0$.
\end{enumerate}
